'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs');
const {environment,examples}=require('./native-fixtures-20261003.cjs'),e=environment(),c=e.ctx,x=examples(c);e.load('prompt-brief');e.load('prompt-packet');
const P=c.JYPromptPacket,plain=x=>JSON.parse(JSON.stringify(x)),results=[];
function test(name,fn){fn();results.push({name,status:'passed'});console.log('PASS '+name);}
function resolve(data){function at(pointer){return pointer.slice(2).split('/').reduce((v,k)=>v[k.replace(/~1/g,'/').replace(/~0/g,'~')],data);}function walk(v){if(!v||typeof v!=='object')return v;if(v.$ref)return walk(at(v.$ref));if(Array.isArray(v))return v.map(walk);return Object.fromEntries(Object.entries(v).map(([k,z])=>[k,walk(z)]));}return P.undense(walk(data));}
function unpack(text){const p=P.get(text);assert(p);assert.equal(text,p.body);const reconstructed=p.parts.map(part=>part.split('【本段內容開始】\n')[1].split('\n【本段內容結束】')[0]).join('');assert.equal(reconstructed,p.body);return {p,data:p.readingData||null};}
for(const [kind,chart]of Object.entries(x.charts))test(kind+' full chart unchanged, complete text, bounded optional parts and actual core facts',()=>{
 const before=JSON.stringify(chart),nativeBefore=JSON.stringify(c.JYNativeAnalysis.analyze(kind,chart)),text=P.build(kind,chart,x.q),{p,data}=unpack(text);
 assert.equal(JSON.stringify(chart),before);assert.equal(JSON.stringify(c.JYNativeAnalysis.analyze(kind,chart)),nativeBefore);
 assert.equal(data.question,x.q);assert.equal(data.method,kind);assert(text.includes('jy.native-analysis/1'));assert(text.includes('"method":"'+kind+'"'));
 p.parts.forEach((part,i)=>{assert(P.chars(part)<=8000);assert(P.utf8(part)<=20000);assert(part.includes('第 '+(i+1)+'／'+p.parts.length+' 段'));assert(!part.includes('undefined'));});
 const sections=data.sections,by=label=>sections.find(s=>s.label===label)?.data;
 if(kind==='bazi'){assert.equal(by('四柱、節令與換日依據').pillars.length,4);assert(by('大運與所問年度').annualSegments.every(y=>y.year>=2026&&y.year<=2029));assert(new Set(by('大運與所問年度').annualSegments.map(y=>y.year)).size===4);}
 if(kind==='ziwei'){assert.equal(by('本命十二宮与指定四化').palaces.length,12);assert.equal(by('運限疊宮').months.length,12);assert.equal(by('本命十二宮与指定四化').northern.flights.length,48);}
 if(kind==='vedic'){assert.equal(Object.keys(by('D1九曜與掌宮相位').planets).length,9);assert.equal(by('十六分盤').length,16);assert.equal(by('六力與Bhava力量').strength.planets.length,7);assert.equal(by('六力與Bhava力量').bhavaStrength.houses.length,12);by('六力與Bhava力量').strength.planets.forEach((p,i)=>{const original=chart.strength.planets[i];assert.equal(p.minimumVirupas,original.minimumVirupas);assert.equal(p.meetsMinimum,original.meetsMinimum);assert.deepEqual(plain(p.ishtaKashta),plain(original.ishtaKashta));});for(const [key,value]of Object.entries(by('八分法所有分盤').vargas)){const original=chart.vargaAshtakavarga[key];for(const [planet,masks]of Object.entries(value.prastaraMasks))masks.forEach((mask,j)=>original.prastara[planet][j].forEach((bit,i)=>assert.equal((mask>>i)&1,bit)));for(const [planet,r]of Object.entries(value.reductions)){assert.deepEqual(plain(r.soav),plain(original.reductions[planet].soav));assert.equal(r.pinda.total,original.reductions[planet].pinda.total);}}}
 if(kind==='astro')assert.equal(Object.keys(by('本次用途、完整星位與宮位').planets).length,12);
 if(kind==='liuren'){const base=by('天地盤、四課三傳與時令');assert.equal(base.plate.length,12);assert.equal(base.courses.length,4);assert.equal(base.transmissions.length,3);assert.equal(by('六十四課三值判定').checks.length,64);const timing=by('取用與候選日實算'),encoding=timing.candidateGroups;assert.equal(encoding.days.length,chart.timing.candidates.length);encoding.days.forEach((row,i)=>{const source=chart.timing.candidates[i],base=Date.parse(row.date+'T00:00:00Z');assert.equal(row.date,source.date);assert.equal(row.dayGanzhi,source.dayGanzhi);assert.equal(base+encoding.timeOffsetsMs[row.timeIndex][0],Date.parse(source.start));assert.equal(base+encoding.timeOffsetsMs[row.timeIndex][1],Date.parse(source.endExclusive));row.conditions.forEach((index,j)=>{const target=encoding.conditionDefinitions[index],original=source.conditions[j];assert.equal(target.branch,original.branch);assert.equal(target.target,original.target);assert.deepEqual(plain(target.why),plain(original.why));target.monthConstraints.forEach((m,k)=>{assert.equal(base+m.startOffsetMs,Date.parse(original.monthConstraints[k].start));assert.equal(base+m.endOffsetMs,Date.parse(original.monthConstraints[k].endExclusive));assert.equal(m.monthlyBroken,original.monthConstraints[k].monthlyBroken);assert.equal(m.dayEmpty,original.monthConstraints[k].dayEmpty);assert.equal(m.season,original.monthConstraints[k].season);});});});}
 if(kind==='liuyao')assert.equal(by('完整起卦與六爻').lines.length,6);
 if(kind==='yijing')assert.equal(by('完整起卦與六爻').lines.length,6);
 if(kind==='name'){assert.deepEqual(plain(by('所有姓名實算').map(n=>n.name)),plain(chart.names.map(n=>n.name)));for(const [i,n]of by('所有姓名實算').entries()){assert.equal(n.fiveGrids.grids.length,5);assert.deepEqual(plain(n.fiveGrids.grids.map(g=>[g.num,g.formula])),plain(chart.names[i].fiveGrids.grids.map(g=>[g.num,g.formula])));assert.deepEqual(plain(n.fiveGrids.sanCai),plain(chart.names[i].fiveGrids.sanCai));assert.deepEqual(plain(n.fiveGrids.yinYang),plain(chart.names[i].fiveGrids.yinYang));}}
 if(p.parts.length>1)assert(p.parts[0].includes('等待下一段'));assert(p.parts.at(-1).includes('【資料結束】'));
});
test('long Unicode question and notes preserved without slicing, including emoji across chunk boundaries',()=>{const q='甲𠀀🧭\n'.repeat(8000)+'問題末尾不能消失',notes='筆記𠮷'.repeat(6000)+'筆記末尾';const {data,p}=unpack(P.build('meihua',x.mh,q,{notes}));assert.equal(data.question,q);assert.equal(data.notes,notes);assert(p.parts.length>3);});
test('JSON table coding preserves zero, false, null, row order and distinct fields',()=>{const data=[{a:0,b:false,c:null},{a:1,b:true,c:'𠀀'},{a:2,b:false,c:''}];assert.deepEqual(plain(P.undense(P.dense(data))),data);});
test('unknown birth time stays partial and does not gain a confirmed hour',()=>{const a=unpack(P.build('bazi',x.b,'工作',{unknown:true})).data;const b=a.sections[0].data;assert.equal(b.pillars.length,3);assert(!a.sections.some(s=>s.label==='大運與所問年度'));assert(!Object.hasOwn(b,'qiyun'));assert(!Object.hasOwn(b,'renyuan'));});
test('all requested Bazi decades retain exact age and UTC bounds; missing requested years are explicit',()=>{const a=unpack(P.build('bazi',x.b,'所有大運流年完整分析')).data.sections.find(s=>s.label==='大運與所問年度').data;assert.equal(a.annualSegments.length,c.JYNativeAnalysis.analyze('bazi',x.b).annualSegments.length);a.decades.forEach((d,i)=>{assert.equal(d.ageStart,x.b.dayun[i].ageStart);assert.equal(d.ageEnd,x.b.dayun[i].ageEnd);assert.deepEqual(plain(d.window),plain(x.b.dayun[i].window));});const m=unpack(P.build('bazi',x.b,'1983至1985逐年')).data.sections.find(s=>s.label==='大運與所問年度').data;assert.deepEqual(plain(m.missingYears),[1983,1984,1985]);});
test('all requested Ziwei years are calculated from effective lunar birth year and virtual age, retaining each decade hua',()=>{const a=unpack(P.build('ziwei',x.z,'所有大運流年完整分析')).data;const layer=a.sections.find(s=>s.label==='運限疊宮').data;layer.decades.forEach((d,i)=>{assert.equal(d.ageStart,x.z.daXian[i].ageStart);assert.equal(d.ageEnd,x.z.daXian[i].ageEnd);assert.deepEqual(plain(d.hua),plain(x.z.daXian[i].hua));assert.equal(d.palaces.length,12);});const expected=x.z.daXian.flatMap(d=>Array.from({length:d.ageEnd-d.ageStart+1},(_,i)=>x.z.lunar.year+d.ageStart+i-1));assert.deepEqual(plain(a.sections.find(s=>s.label==='流年輸出範圍').data.requestedYears),plain(expected));assert.equal(a.sections.find(s=>s.label==='明示年度流年').data.length,expected.filter(y=>y!==x.z.calculationPolicy.referenceLunarYear).length);});
test('unknown Ziwei and Vedic clocks do not yield confirmed houses or active dashas',()=>{const z=c.computeZiwei(1983,8,25,12,'male',{btimeUnknown:true,referenceDate:x.instant}),zs=unpack(P.build('ziwei',z,'工作')).data.sections;assert(!zs.some(s=>s.label==='本命十二宮与指定四化'));const v=c.JYVedic.compute({...x.input,unknownTime:true}),vs=unpack(P.build('vedic',v,'工作')).data.sections;const core=vs.find(s=>s.label==='D1九曜與掌宮相位').data;assert.equal(core.lagna,null);assert.equal(core.houses.length,0);assert(Object.values(core.planets).every(p=>p.house===null));assert.equal(vs.find(s=>s.label==='所問運期與行運').data.vimshottari.current,null);});
test('requested all sixteen vargas includes all detailed AV tables; topic choice cannot silently discard requested vargas',()=>{const {data}=unpack(P.build('vedic',x.v,'所有十六分盤都完整分析'));assert.equal(Object.keys(data.sections.find(s=>s.label==='八分法所有分盤').data.vargas).length,16);});
test('composite finish expands every embedded packet and remains idempotent',()=>{const a=P.build('tarot',x.tarot,'同題'),b=P.build('oracle',x.oracle,'同題'),text=c.JYReadingWorkflow.finish(a+'\n'+b,{methods:['tarot','oracle'],question:'同題'}),p=P.get(text);assert(!p.body.includes('【命理分析資料 '));assert(p.body.includes('本次所有牌籤'));assert.equal(c.JYReadingWorkflow.finish(text,{method:'tarot'}),text);});
